SELECT

FROM `organization` o
LEFT JOIN `organization` p ON o.parent_id = p.id AND p.deleted = 0
WHERE o.deleted = 0

    AND o.org_name LIKE CONCAT('%', #{query.orgName}, '%')


    AND o.org_type = #{query.orgType}


    AND o.parent_id = #{query.parentId}

ORDER BY o.create_time DESC

    LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT COUNT(*)
FROM `organization` o
WHERE o.deleted = 0

    AND o.org_name LIKE CONCAT('%', #{query.orgName}, '%')


    AND o.org_type = #{query.orgType}


    AND o.parent_id = #{query.parentId}

